  (* [comment removed for export] *)
  Theorem free_exit1 : forall s msF mo regs mem p (A cap : Z) (status : word) junk,
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbeb14) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 ATP -> getr regs 8 = status -> getr regs 9 = Z_to_bv 64 A ->
    bv_unsigned status < 256 ->
    as_RHEAP H s [(p, A, cap)] mem -> rw_cells asegs mem A [CB (Z.to_nat cap) junk] -> addressable mem A cap ->
    as_Cf H cap <= as_AL H s ->
    xstat adrv_ax1 mem -> ostate [] mem ->
    realizes asegs (mkCfg msF mo) (t_exit (bv_and status (Z_to_bv 64 255)) (m_fs mo)).
Proof.
